import{_ as t,o as e,c as i,a8 as o}from"./chunks/framework.BppdKxCY.js";const g=JSON.parse('{"title":"EP.13 SSR 与水合","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.13-ssr-hydration.md","filePath":"comics/EP.13-ssr-hydration.md","lastUpdated":1793421673000}'),s={name:"comics/EP.13-ssr-hydration.md"};function l(r,a,n,d,h,c){return e(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="ep-13-ssr-与水合" tabindex="-1">EP.13 SSR 与水合 <a class="header-anchor" href="#ep-13-ssr-与水合" aria-label="Permalink to &quot;EP.13 SSR 与水合&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../13-ssr-meta-frameworks">13-ssr-meta-frameworks.md</a>（13.1 渲染模式全景 / 13.2 Hydration 原理与疑难排查）· 示例：<code>examples/13-01-ssr-manual.ts</code>、<code>examples/13-02-hydration-safe.tsx</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：标签君的 CSR 页面首屏白屏三秒——HTML 是空壳，全等 JS 下载执行。</li><li><strong>第 2 格</strong>：码叔揭秘渲染模式全景：CSR/SSR/SSG/ISR，首屏速度依次 SSG ≈ ISR &gt; SSR &gt; CSR。</li><li><strong>第 3 格</strong>：像素酱实证水合：JS 接管服务端 HTML 并挂事件，两端结果必须一致。</li><li><strong>第 4 格</strong>：码叔结案——流式 SSR 分块送达、选择性水合让交互区先可用。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-csr-的白屏根源" tabindex="-1">第 1 格 · CSR 的白屏根源 <a class="header-anchor" href="#第-1-格-·-csr-的白屏根源" aria-label="Permalink to &quot;第 1 格 · CSR 的白屏根源&quot;">​</a></h3><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;root&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 首个响应只有空壳 --&gt;</span></span></code></pre></div><ul><li>用户要等：HTML → JS 下载 → JS 执行 → 渲染，四步全串行；</li><li>SEO 也不友好：爬虫拿到的是空壳；</li><li>解法：把「渲染」提前到服务端做。</li></ul><h3 id="第-2-格-·-渲染模式全景" tabindex="-1">第 2 格 · 渲染模式全景 <a class="header-anchor" href="#第-2-格-·-渲染模式全景" aria-label="Permalink to &quot;第 2 格 · 渲染模式全景&quot;">​</a></h3><ul><li><strong>CSR</strong>：客户端渲染，适合重交互后台；</li><li><strong>SSR</strong>：每请求服务端渲染，内容始终新鲜，服务器有压力；</li><li><strong>SSG</strong>：构建时产出静态 HTML，CDN 直接回，最快；</li><li><strong>ISR</strong>：SSG + 按需/定时再生成，兼顾新鲜与快（Next.js <code>revalidate</code>）。</li></ul><h3 id="第-3-格-·-水合-hydration" tabindex="-1">第 3 格 · 水合（Hydration） <a class="header-anchor" href="#第-3-格-·-水合-hydration" aria-label="Permalink to &quot;第 3 格 · 水合（Hydration）&quot;">​</a></h3><ul><li>服务端 HTML 先到（<strong>用户立刻能看</strong>），客户端 JS 再「接管」：复用 DOM、挂事件、绑定状态；</li><li>接管时客户端必须渲染出<strong>与 HTML 完全一致</strong>的结构，否则抛 hydration mismatch；</li><li>三大 mismatch 元凶：<code>new Date()</code>（两端时间不同）、<code>Math.random()</code>、<a href="https://developer.mozilla.org/zh-CN/docs/Web/API/Window/localStorage" target="_blank" rel="noopener noreferrer" title="MDN 文档"><code>localStorage</code></a>（服务端不存在）；</li><li>修法：时间/随机值由服务端下发或两端统一，浏览器专属值放到 <code>mounted</code>/<code>useEffect</code> 之后再渲染。</li></ul><h3 id="第-4-格-·-流式与选择性水合" tabindex="-1">第 4 格 · 流式与选择性水合 <a class="header-anchor" href="#第-4-格-·-流式与选择性水合" aria-label="Permalink to &quot;第 4 格 · 流式与选择性水合&quot;">​</a></h3><ul><li><strong>流式 SSR</strong>：<code>renderToPipeableStream</code> 分块推送，先到的先渲染，不用等全页就绪；</li><li><strong>选择性水合</strong>：交互优先——用户点哪块，哪块先水合，其余排队；</li><li>RSC（服务端组件）进一步把「不交互的部分」留在服务端，客户端 JS 体积骤减。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../13-ssr-meta-frameworks#_13-6-本章避坑清单">《13.6 本章避坑清单》</a></p></blockquote><ol><li>hydration mismatch：时间/随机/localStorage 导致两端渲染不一致，控制台报错且整树重建；</li><li>水合完成前直接操作 DOM（或第三方插件改 DOM）：水合时结构对不上，轻则重渲染重则崩溃；</li><li>在服务端组件/SSR 环境里用 <code>window</code>/<code>document</code>：服务端没有这些对象，直接 ReferenceError。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>CSR/SSR/SSG/ISR 怎么选？——<strong>重交互后台选 CSR；内容新鲜度高的选 SSR；内容基本静态选 SSG；静态为主但需定时更新选 ISR</strong>。</li><li>什么是 hydration mismatch？举两个常见诱因？——<strong>客户端接管时渲染结果与服务端 HTML 不一致；诱因如 new Date() 两端时间不同、localStorage 服务端不存在</strong>。</li><li>流式 SSR 的好处？——<strong>HTML 分块推送，先就绪先展示；配合选择性水合，用户交互的区域优先变得可交互</strong>。</li></ol>',19)])])}const p=t(s,[["render",l]]);export{g as __pageData,p as default};
